};

/**
 * Configuration loader for Tide Watch
 * 
 * Precedence (highest to lowest):
 * 1. CLI flags (explicit user intent)
 * 2. Environment variables (session override)
 * 3. Config file (persistent preferences)
 * 4. Defaults (safe fallback)
 */

const fs = require('fs');
const path = require('path');
const os = require('os');

// Safe, tested defaults from v1.1.5
const DEFAULTS = {
  refreshInterval: 10,   // Dashboard watch refresh (seconds)
  gatewayInterval: 30,   // Gateway status check interval (seconds)
  gatewayTimeout: 3      // Gateway command timeout (seconds)
};

// User config location (XDG standard)
const CONFIG_PATH = path.join(os.homedir(), '.config', 'tide-watch', 'config.json');

/**
 * Validate configuration values
 * @param {Object} config - Configuration object to validate
 * @returns {Object} Validated config
 * @throws {Error} If validation fails
 */
function validateConfig(config) {
  const rules = {
    refreshInterval: { min: 1, max: 300, desc: 'Dashboard refresh interval' },
    gatewayInterval: { min: 5, max: 600, desc: 'Gateway status check interval' },
    gatewayTimeout: { min: 1, max: 30, desc: 'Gateway command timeout' }
  };

  const validated = {};

  for (const [key, value] of Object.entries(config)) {
    // Whitelist: only known keys allowed
    if (!rules[key]) {
      throw new Error(`Unknown config key: ${key}`);
    }

    const { min, max, desc } = rules[key];
    const num = parseInt(value, 10);

    // Type and range validation
    if (isNaN(num) || num < min || num > max) {
      throw new Error(`Invalid ${key}: must be between ${min} and ${max} seconds (${desc})`);
    }

    validated[key] = num;
  }

  return validated;
}

/**
 * Load configuration from file (if exists)
 * @returns {Object} Config from file, or empty object if file doesn't exist
 */
function loadConfigFile() {
  if (!fs.existsSync(CONFIG_PATH)) {
    return {};
  }

  try {
    const content = fs.readFileSync(CONFIG_PATH, 'utf8');
    const parsed = JSON.parse(content);

    // Validate file config before using it
    return validateConfig(parsed);
  } catch (error) {
    console.warn(`Warning: Could not load config file (${CONFIG_PATH}): ${error.message}`);
    console.warn('Continuing with defaults...');
    return {};
  }
}

/**
 * Load configuration from environment variables
 * @returns {Object} Config from env vars
 */
function loadEnvConfig() {
  const config = {};

  if (process.env.TIDE_WATCH_REFRESH_INTERVAL) {
    config.refreshInterval = process.env.TIDE_WATCH_REFRESH_INTERVAL;
  }
  if (process.env.TIDE_WATCH_GATEWAY_INTERVAL) {
    config.gatewayInterval = process.env.TIDE_WATCH_GATEWAY_INTERVAL;
  }
  if (process.env.TIDE_WATCH_GATEWAY_TIMEOUT) {
    config.gatewayTimeout = process.env.TIDE_WATCH_GATEWAY_TIMEOUT;
  }

  // Validate env config if any values present
  if (Object.keys(config).length > 0) {
    return validateConfig(config);
  }

  return {};
}

/**
 * Load configuration with full precedence chain
 * @param {Object} cliFlags - CLI flags (highest precedence)
 * @returns {Object} Final merged and validated configuration
 */
function loadConfig(cliFlags = {}) {
  // 1. Start with safe defaults
  let config = { ...DEFAULTS };

  // 2. Merge config file (if exists and valid)
  const fileConfig = loadConfigFile();
  config = { ...config, ...fileConfig };

  // 3. Merge environment variables
  const envConfig = loadEnvConfig();
  config = { ...config, ...envConfig };

  // 4. Merge CLI flags (highest priority)
  if (Object.keys(cliFlags).length > 0) {
    const validatedFlags = validateConfig(cliFlags);
    config = { ...config, ...validatedFlags };
  }

  return config;
}

/**
 * Create config directory with secure permissions
 * @returns {boolean} True if directory exists/was created
 */
function ensureConfigDir() {
  const configDir = path.dirname(CONFIG_PATH);

  if (fs.existsSync(configDir)) {
    return true;
  }

  try {
    // Create directory with user-only permissions (0700)
    fs.mkdirSync(configDir, { recursive: true, mode: 0o700 });
    return true;
  } catch (error) {
    console.warn(`Warning: Could not create config directory: ${error.message}`);
    return false;
  }
}

/**
 * Save configuration to file with secure permissions
 * @param {Object} config - Configuration to save
 * @returns {boolean} True if saved successfully
 */
function saveConfig(config) {
  // Validate before saving
  const validated = validateConfig(config);

  // Ensure directory exists
  if (!ensureConfigDir()) {
    return false;
  }

  try {
    // Write with user-only permissions (0600)
    const content = JSON.stringify(validated, null, 2);
    fs.writeFileSync(CONFIG_PATH, content, { mode: 0o600 });
    return true;
  } catch (error) {
    console.error(`Error: Could not save config file: ${error.message}`);
    return false;
  }
}

module.exports = {
  loadConfig,
  saveConfig,
  validateConfig,
  DEFAULTS,
  CONFIG_PATH
};

#!/usr/bin/env node

/**
 * Monitoring utilities for Tide Watch
 * Helpers for parsing configuration and generating warnings
 */

/**
 * Parse monitoring configuration from AGENTS.md content
 * @param {string} content - AGENTS.md file content
 * @returns {Object} Parsed configuration
 */
function parseMonitoringConfig(content) {
  const config = {
    checkFrequency: 60, // default: 1 hour in minutes
    thresholds: [75, 85, 90, 95], // default thresholds
    autoBackup: {
      enabled: true,
      triggerAt: [90, 95],
      retention: 7,
      compress: false
    }
  };

  // Parse check frequency
  const frequencyMatch = content.match(/Check frequency:\s*\*\*Every\s+(\d+)\s+(min(?:ute)?s?|h(?:ou)?rs?)\*\*/i);
  if (frequencyMatch) {
    const value = parseInt(frequencyMatch[1], 10);
    const unit = frequencyMatch[2].toLowerCase();

    if (unit.startsWith('h')) {
      config.checkFrequency = value * 60;
    } else {
      config.checkFrequency = value;
    }
  }

  // Check for manual mode
  if (content.match(/Check frequency:\s*\*\*manual\*\*/i)) {
    config.checkFrequency = null; // null = manual mode
  }

  // Parse warning thresholds
  const thresholdMatches = content.matchAll(/\*\*(\d+)%\*\*\s*[:\-]?\s*(?:🟡|🟠|🔴|🚨)/g);
  const parsedThresholds = [];

  for (const match of thresholdMatches) {
    const threshold = parseInt(match[1], 10);
    if (threshold >= 50 && threshold <= 99) {
      parsedThresholds.push(threshold);
    }
  }

  if (parsedThresholds.length >= 2) {
    // Validate ascending order
    const sorted = [...parsedThresholds].sort((a, b) => a - b);
    if (JSON.stringify(sorted) === JSON.stringify(parsedThresholds)) {
      config.thresholds = parsedThresholds;
    }
  }

  // Parse auto-backup settings
  const backupEnabledMatch = content.match(/Enabled:\s*(true|false)/i);
  if (backupEnabledMatch) {
    config.autoBackup.enabled = backupEnabledMatch[1].toLowerCase() === 'true';
  }

  const backupThresholdsMatch = content.match(/Trigger at thresholds:\s*\[([^\]]+)\]/);
  if (backupThresholdsMatch) {
    const triggers = backupThresholdsMatch[1]
      .split(',')
      .map(s => parseInt(s.trim(), 10))
      .filter(n => !isNaN(n));

    if (triggers.length > 0) {
      config.autoBackup.triggerAt = triggers;
    }
  }

  const retentionMatch = content.match(/Retention:\s*(\d+)\s*days?/i);
  if (retentionMatch) {
    config.autoBackup.retention = parseInt(retentionMatch[1], 10);
  }

  const compressMatch = content.match(/Compress:\s*(true|false)/i);
  if (compressMatch) {
    config.autoBackup.compress = compressMatch[1].toLowerCase() === 'true';
  }

  return config;
}

/**
 * Determine which threshold was crossed (if any)
 * @param {number} currentPercentage - Current capacity percentage
 * @param {Array<number>} thresholds - Configured thresholds
 * @param {Array<number>} warnedThresholds - Thresholds already warned about
 * @returns {number|null} Threshold that was crossed, or null
 */
function checkThresholdCrossed(currentPercentage, thresholds, warnedThresholds = []) {
  // Find the highest threshold that's been crossed but not yet warned
  for (let i = thresholds.length - 1; i >= 0; i--) {
    const threshold = thresholds[i];
    if (currentPercentage >= threshold && !warnedThresholds.includes(threshold)) {
      return threshold;
    }
  }
  return null;
}

/**
 * Generate warning message for a threshold
 * @param {number} threshold - Threshold percentage
 * @param {Array<number>} thresholds - All configured thresholds
 * @param {number} tokensUsed - Tokens used
 * @param {number} tokensMax - Maximum tokens
 * @param {string} channel - Channel name (optional)
 * @returns {string} Warning message
 */
function generateWarningMessage(threshold, thresholds, tokensUsed, tokensMax, channel = null) {
  const thresholdIndex = thresholds.indexOf(threshold);
  const isFirst = thresholdIndex === 0;
  const isLast = thresholdIndex === thresholds.length - 1;
  const isSecondToLast = thresholdIndex === thresholds.length - 2;

  // Determine severity emoji
  let emoji;
  if (isLast) {
    emoji = '🚨';
  } else if (isSecondToLast) {
    emoji = '🔴';
  } else if (isFirst) {
    emoji = '🟡';
  } else {
    emoji = '🟠';
  }

  // Build message
  const lines = [];

  // Header
  if (isLast) {
    lines.push(`${emoji} **CRITICAL: Context at ${threshold}%!**`);
  } else if (isSecondToLast) {
    lines.push(`${emoji} **Context at ${threshold}%!**`);
  } else if (isFirst) {
    lines.push(`${emoji} Heads up: Context at ${threshold}%.`);
  } else {
    lines.push(`${emoji} Context at ${threshold}%.`);
  }

  // Capacity details
  lines.push(`Tokens: ${tokensUsed.toLocaleString()} / ${tokensMax.toLocaleString()}`);
  if (channel) {
    lines.push(`Session: ${channel}`);
  }

  lines.push(''); // blank line

  // Recommendations based on severity
  if (isLast) {
    lines.push('**Save important info to memory NOW and reset.**');
    lines.push('Session will lock at 100% capacity.');
  } else if (isSecondToLast) {
    lines.push('**Session will lock soon! Ready to help you reset?**');
    lines.push('Recommend finishing current task and resetting session.');
  } else if (thresholdIndex === thresholds.length - 3) {
    lines.push('**Recommend finishing current task and resetting session.**');
  } else if (isFirst) {
    lines.push('Consider wrapping up or switching channels soon.');
  } else {
    lines.push('Consider wrapping up soon and switching to a fresh session.');
  }

  return lines.join('\n');
}

/**
 * Determine if auto-backup should be triggered
 * @param {number} currentPercentage - Current capacity percentage
 * @param {Object} autoBackupConfig - Auto-backup configuration
 * @param {Array<number>} backedUpThresholds - Thresholds already backed up
 * @returns {number|null} Threshold that should trigger backup, or null
 */
function shouldTriggerBackup(currentPercentage, autoBackupConfig, backedUpThresholds = []) {
  if (!autoBackupConfig.enabled) {
    return null;
  }

  // Find the highest backup trigger threshold that's been crossed but not yet backed up
  for (let i = autoBackupConfig.triggerAt.length - 1; i >= 0; i--) {
    const threshold = autoBackupConfig.triggerAt[i];
    if (currentPercentage >= threshold && !backedUpThresholds.includes(threshold)) {
      return threshold;
    }
  }

  return null;
}

/**
 * Generate session reset prompt with context preservation
 * @param {string} sessionId - Session identifier
 * @param {Object} sessionData - Current session data
 * @returns {string} Reset prompt
 */
function generateResetPrompt(sessionId, sessionData = {}) {
  const lines = [];

  lines.push('## Session Reset with Context Preservation');
  lines.push('');
  lines.push('**Before resetting:**');
  lines.push('1. ✅ Save current work to memory/YYYY-MM-DD.md');
  lines.push('2. ✅ Backup session file (if not already backed up)');
  lines.push('3. ✅ Note any pending tasks or decisions');
  lines.push('');
  lines.push('**Reset command:**');
  lines.push('```');
  lines.push('New session, please');
  lines.push('```');
  lines.push('');
  lines.push('**After reset:**');
  lines.push('1. Review memory/YYYY-MM-DD.md for context');
  lines.push('2. Continue from where you left off');

  if (sessionData.channel) {
    lines.push('');
    lines.push(`**Alternative:** Switch to lower-capacity session`);
    lines.push(`Current session: ${sessionData.channel} (${sessionData.percentage}%)`);
  }

  return lines.join('\n');
}

module.exports = {
  parseMonitoringConfig,
  checkThresholdCrossed,
  generateWarningMessage,
  shouldTriggerBackup,
  generateResetPrompt
};

#!/usr/bin/env node

/**
 * Session resumption prompt management
 * Helps recover context after session resets
 */

const fs = require('fs');
const path = require('path');
const os = require('os');
const { spawnSync } = require('child_process');

/**
 * Default resumption prompts directory
 */
const DEFAULT_RESUME_DIR = path.join(
  os.homedir(),
  '.openclaw',
  'agents',
  'main',
  'sessions',
  'resume-prompts'
);

/**
 * Path to global discovery marker file
 */
const DISCOVERY_MARKER = '.no-discovery';

/**
 * Get resumption prompt path for a session
 * @param {string} sessionId - Session identifier
 * @param {string} resumeDir - Resumption prompts directory
 * @returns {string} Path to resumption prompt file
 */
function getResumePromptPath(sessionId, resumeDir = DEFAULT_RESUME_DIR) {
  return path.join(resumeDir, `${sessionId}.md`);
}

/**
 * Get default resumption prompt path
 * @param {string} resumeDir - Resumption prompts directory
 * @returns {string} Path to default resumption prompt file
 */
function getDefaultResumePromptPath(resumeDir = DEFAULT_RESUME_DIR) {
  return path.join(resumeDir, 'default.md');
}

/**
 * Check if resumption prompt exists for session
 * @param {string} sessionId - Session identifier
 * @param {string} resumeDir - Resumption prompts directory
 * @returns {boolean} True if prompt exists
 */
function hasResumePrompt(sessionId, resumeDir = DEFAULT_RESUME_DIR) {
  const promptPath = getResumePromptPath(sessionId, resumeDir);
  return fs.existsSync(promptPath);
}

/**
 * Load resumption prompt for session
 * @param {string} sessionId - Session identifier
 * @param {string} resumeDir - Resumption prompts directory
 * @returns {string|null} Resumption prompt content, or null if not found
 */
function loadResumePrompt(sessionId, resumeDir = DEFAULT_RESUME_DIR) {
  // Try session-specific prompt first
  const sessionPromptPath = getResumePromptPath(sessionId, resumeDir);
  if (fs.existsSync(sessionPromptPath)) {
    return fs.readFileSync(sessionPromptPath, 'utf8');
  }

  // Fall back to default prompt
  const defaultPromptPath = getDefaultResumePromptPath(resumeDir);
  if (fs.existsSync(defaultPromptPath)) {
    return fs.readFileSync(defaultPromptPath, 'utf8');
  }

  return null;
}

/**
 * Save resumption prompt for session
 * @param {string} sessionId - Session identifier
 * @param {string} content - Prompt content
 * @param {string} resumeDir - Resumption prompts directory
 */
function saveResumePrompt(sessionId, content, resumeDir = DEFAULT_RESUME_DIR) {
  // Ensure directory exists
  if (!fs.existsSync(resumeDir)) {
    fs.mkdirSync(resumeDir, { recursive: true });
  }

  const promptPath = getResumePromptPath(sessionId, resumeDir);
  fs.writeFileSync(promptPath, content, 'utf8');
}

/**
 * Delete resumption prompt for session
 * @param {string} sessionId - Session identifier
 * @param {string} resumeDir - Resumption prompts directory
 * @returns {boolean} True if deleted, false if didn't exist
 */
function deleteResumePrompt(sessionId, resumeDir = DEFAULT_RESUME_DIR) {
  const promptPath = getResumePromptPath(sessionId, resumeDir);

  if (!fs.existsSync(promptPath)) {
    return false;
  }

  fs.unlinkSync(promptPath);
  return true;
}

/**
 * List all resumption prompts
 * @param {string} resumeDir - Resumption prompts directory
 * @returns {Array} Array of {sessionId, path, size, modified, enabled}
 */
function listResumePrompts(resumeDir = DEFAULT_RESUME_DIR) {
  if (!fs.existsSync(resumeDir)) {
    return [];
  }

  const files = fs.readdirSync(resumeDir);
  const prompts = [];

  for (const file of files) {
    if (!file.endsWith('.md')) {
      continue;
    }

    const filePath = path.join(resumeDir, file);
    const stats = fs.statSync(filePath);
    const sessionId = file === 'default.md' ? 'default' : path.basename(file, '.md');
    const enabled = isResumePromptEnabled(sessionId, resumeDir);

    prompts.push({
      sessionId,
      path: filePath,
      size: stats.size,
      modified: stats.mtime,
      enabled
    });
  }

  return prompts.sort((a, b) => b.modified - a.modified);
}

/**
 * Open resumption prompt in editor
 * @param {string} sessionId - Session identifier
 * @param {string} resumeDir - Resumption prompts directory
 * @returns {boolean} True if editor opened successfully
 */
function editResumePrompt(sessionId, resumeDir = DEFAULT_RESUME_DIR) {
  // Ensure directory exists
  if (!fs.existsSync(resumeDir)) {
    fs.mkdirSync(resumeDir, { recursive: true });
  }

  const promptPath = getResumePromptPath(sessionId, resumeDir);

  // Create template if doesn't exist
  if (!fs.existsSync(promptPath)) {
    const template = generateResumePromptTemplate(sessionId);
    fs.writeFileSync(promptPath, template, 'utf8');
  }

  // Determine editor
  const editor = process.env.VISUAL || process.env.EDITOR || 'nano';

  try {
    // Use spawnSync with array args to prevent shell injection
    // This avoids shell metacharacter expansion in sessionId/promptPath
    const result = spawnSync(editor, [promptPath], { 
      stdio: 'inherit',
      shell: false  // Explicitly disable shell to prevent injection
    });

    if (result.error) {
      throw result.error;
    }

    return true;
  } catch (error) {
    console.error(`Failed to open editor: ${error.message}`);
    return false;
  }
}

/**
 * Generate resumption prompt template
 * @param {string} sessionId - Session identifier
 * @returns {string} Template content
 */
function generateResumePromptTemplate(sessionId) {
  return `# Session Restoration Prompt

**Session ID:** ${sessionId}
**Created:** ${new Date().toISOString().split('T')[0]}

## Project Context

**Project Name:** [Your project name]
**Description:** [Brief description]

## Technical Details

**Tech Stack:** [Technologies, languages, frameworks]
**Environment:** [Development environment, tools]

## Current Focus

**Phase:** [Current project phase]
**Last Completed:** [What was recently finished]
**Next Steps:** [What's coming up]

## Important Files & Locations

**Code:** [Path to code directory]
**Docs:** [Path to documentation]
**Data:** [Path to data/assets]

## Active Work

**Current Tasks:**
- [Task 1]
- [Task 2]
- [Task 3]

**Blockers:** [Any current blockers or dependencies]

## Team & Communication

**Team Members:** [If applicable]
**Communication Channels:** [Discord, Slack, etc.]
**Schedule:** [Stand-ups, meetings, etc.]

## Custom Instructions

[Any specific instructions for how the agent should behave in this session]

---

**Tips:**
- Keep this updated as your project evolves
- Be concise but thorough (aim for < 1000 tokens)
- Include only essential context for quick recovery
- Update after major project milestones
`;
}

/**
 * Get resumption prompt metadata
 * @param {string} sessionId - Session identifier
 * @param {string} resumeDir - Resumption prompts directory
 * @returns {Object|null} Metadata or null if not found
 */
function getResumePromptInfo(sessionId, resumeDir = DEFAULT_RESUME_DIR) {
  const promptPath = getResumePromptPath(sessionId, resumeDir);

  if (!fs.existsSync(promptPath)) {
    return null;
  }

  const stats = fs.statSync(promptPath);
  const content = fs.readFileSync(promptPath, 'utf8');

  // Estimate token count (rough approximation: 1 token ≈ 4 characters)
  const estimatedTokens = Math.ceil(content.length / 4);

  return {
    sessionId,
    path: promptPath,
    size: stats.size,
    lines: content.split('\n').length,
    estimatedTokens,
    modified: stats.mtime,
    created: stats.birthtime
  };
}

/**
 * Format resumption prompt info for display
 * @param {Object} info - Prompt metadata
 * @returns {string} Formatted display text
 */
function formatResumePromptInfo(info) {
  const lines = [];

  lines.push(`Session: ${info.sessionId}`);
  lines.push(`Path: ${info.path}`);
  lines.push(`Size: ${info.size} bytes (${info.lines} lines)`);
  lines.push(`Estimated tokens: ~${info.estimatedTokens}`);
  lines.push(`Modified: ${info.modified.toLocaleString()}`);

  if (info.estimatedTokens > 1000) {
    lines.push('');
    lines.push('⚠️  Warning: Prompt is large (>1000 tokens). Consider shortening for better efficiency.');
  }

  return lines.join('\n');
}

/**
 * Check if resumption prompt is enabled
 * @param {string} sessionId - Session identifier
 * @param {string} resumeDir - Resumption prompts directory
 * @returns {boolean} True if enabled (no .disabled marker)
 */
function isResumePromptEnabled(sessionId, resumeDir = DEFAULT_RESUME_DIR) {
  const promptPath = getResumePromptPath(sessionId, resumeDir);
  const disabledPath = `${promptPath}.disabled`;

  // Enabled if prompt exists and no .disabled marker
  return fs.existsSync(promptPath) && !fs.existsSync(disabledPath);
}

/**
 * Disable resumption prompt for session
 * @param {string} sessionId - Session identifier
 * @param {string} resumeDir - Resumption prompts directory
 * @returns {boolean} True if disabled, false if prompt doesn't exist
 */
function disableResumePrompt(sessionId, resumeDir = DEFAULT_RESUME_DIR) {
  const promptPath = getResumePromptPath(sessionId, resumeDir);

  if (!fs.existsSync(promptPath)) {
    return false;
  }

  const disabledPath = `${promptPath}.disabled`;
  fs.writeFileSync(disabledPath, '', 'utf8');
  return true;
}

/**
 * Enable resumption prompt for session
 * @param {string} sessionId - Session identifier
 * @param {string} resumeDir - Resumption prompts directory
 * @returns {boolean} True if enabled, false if prompt doesn't exist
 */
function enableResumePrompt(sessionId, resumeDir = DEFAULT_RESUME_DIR) {
  const promptPath = getResumePromptPath(sessionId, resumeDir);

  if (!fs.existsSync(promptPath)) {
    return false;
  }

  const disabledPath = `${promptPath}.disabled`;

  if (fs.existsSync(disabledPath)) {
    fs.unlinkSync(disabledPath);
  }

  return true;
}

/**
 * Get resumption prompt status
 * @param {string} sessionId - Session identifier
 * @param {string} resumeDir - Resumption prompts directory
 * @returns {Object|null} Status object or null if prompt doesn't exist
 */
function getResumePromptStatus(sessionId, resumeDir = DEFAULT_RESUME_DIR) {
  const promptPath = getResumePromptPath(sessionId, resumeDir);

  if (!fs.existsSync(promptPath)) {
    return null;
  }

  const info = getResumePromptInfo(sessionId, resumeDir);
  const enabled = isResumePromptEnabled(sessionId, resumeDir);

  return {
    ...info,
    enabled,
    autoLoad: enabled,
    disabledMarkerPath: enabled ? null : `${promptPath}.disabled`
  };
}

/**
 * Format resumption prompt status for display
 * @param {Object} status - Status object
 * @returns {string} Formatted status text
 */
function formatResumePromptStatus(status) {
  const lines = [];

  lines.push(`Session: ${status.sessionId}`);
  lines.push(`Prompt: ✅ Exists (${status.size} bytes, ${status.lines} lines)`);
  lines.push(`Status: ${status.enabled ? '✅ Enabled' : '⏸️  Disabled'}`);
  lines.push(`Auto-load: ${status.autoLoad ? '✅ Will auto-load on session reset' : '❌ Will NOT auto-load'}`);

  if (!status.enabled) {
    lines.push(`Marker file: ${status.disabledMarkerPath}`);
  }

  lines.push(`Modified: ${status.modified.toLocaleString()}`);
  lines.push(`Estimated tokens: ~${status.estimatedTokens}`);

  return lines.join('\n');
}

/**
 * Check if feature discovery is enabled
 * @param {string} resumeDir - Resumption prompts directory
 * @returns {boolean} True if discovery enabled (no .no-discovery marker)
 */
function isDiscoveryEnabled(resumeDir = DEFAULT_RESUME_DIR) {
  const markerPath = path.join(resumeDir, DISCOVERY_MARKER);
  return !fs.existsSync(markerPath);
}

/**
 * Disable feature discovery globally
 * @param {string} resumeDir - Resumption prompts directory
 * @returns {boolean} True if disabled successfully
 */
function disableDiscovery(resumeDir = DEFAULT_RESUME_DIR) {
  // Ensure directory exists
  if (!fs.existsSync(resumeDir)) {
    fs.mkdirSync(resumeDir, { recursive: true });
  }

  const markerPath = path.join(resumeDir, DISCOVERY_MARKER);
  fs.writeFileSync(markerPath, '# Discovery disabled by user\n', 'utf8');
  return true;
}

/**
 * Enable feature discovery globally
 * @param {string} resumeDir - Resumption prompts directory
 * @returns {boolean} True if enabled successfully
 */
function enableDiscovery(resumeDir = DEFAULT_RESUME_DIR) {
  const markerPath = path.join(resumeDir, DISCOVERY_MARKER);

  if (fs.existsSync(markerPath)) {
    fs.unlinkSync(markerPath);
  }

  return true;
}

/**
 * Get feature discovery status
 * @param {string} resumeDir - Resumption prompts directory
 * @returns {Object} Discovery status
 */
function getDiscoveryStatus(resumeDir = DEFAULT_RESUME_DIR) {
  const enabled = isDiscoveryEnabled(resumeDir);
  const markerPath = path.join(resumeDir, DISCOVERY_MARKER);

  return {
    enabled,
    markerPath: enabled ? null : markerPath,
    markerExists: fs.existsSync(markerPath)
  };
}

/**
 * Format discovery status for display
 * @param {Object} status - Discovery status object
 * @returns {string} Formatted status text
 */
function formatDiscoveryStatus(status) {
  const lines = [];

  lines.push('Feature Discovery Status: ' + (status.enabled ? '✅ Enabled' : '⏸️  Disabled'));
  lines.push('');
  lines.push('Discovery prompts: ' + (status.enabled ? 'ON' : 'OFF'));

  if (!status.enabled) {
    lines.push('- No creation offers after resets');
    lines.push('- No capacity warning reminders');
    lines.push('');
    lines.push(`Marker file: ${status.markerPath}`);
  } else {
    lines.push('- Creation offers after resets: ✅');
    lines.push('- Capacity warning reminders: ✅');
  }

  lines.push('');
  lines.push('Restoration features: ON');
  lines.push('- Auto-loading: ✅ Works normally');
  lines.push('- Manual trigger: ✅ Works normally');
  lines.push('- CLI commands: ✅ All available');

  return lines.join('\n');
}

module.exports = {
  DEFAULT_RESUME_DIR,
  getResumePromptPath,
  getDefaultResumePromptPath,
  hasResumePrompt,
  loadResumePrompt,
  saveResumePrompt,
  deleteResumePrompt,
  listResumePrompts,
  editResumePrompt,
  generateResumePromptTemplate,
  getResumePromptInfo,
  formatResumePromptInfo,
  isResumePromptEnabled,
  disableResumePrompt,
  enableResumePrompt,
  getResumePromptStatus,
  formatResumePromptStatus,
  isDiscoveryEnabled,
  disableDiscovery,
  enableDiscovery,
  getDiscoveryStatus,
  formatDiscoveryStatus
};

